<script lang="ts">
  import Button from '../../ui/Button.svelte';
  import { onDestroy,onMount } from 'svelte';
  import { Mic,Square,Copy,ClipboardPaste,X,RefreshCw } from '@lucide/svelte';
  import Select from '../../ui/Select.svelte';
  import { applyAppearance,loadAppearance } from '../../settings/appearance';
  import { remoteBackend } from '../../platform/remote-backend';
  import { productionJson } from '../production/production';
  import { isDesktop } from '../../platform/runtime';
  import { LiveDictation,emptyDictation,type DictationCatalog,type DictationPhase,type DictationTranscript } from './dictation';
  import { acknowledgeDictationStopped,acquireWidgetRuntime,copyDesktopDictation,desktopDictationStatus,hideDictationWidget,pasteDesktopDictation,watchDesktopDictation,type DictationDesktopStatus } from './dictation-desktop';
  import workletUrl from './dictation-worklet.js?url&no-inline';
  const uid=$props.id(),desktop=isDesktop();
  let status=$state<DictationDesktopStatus>(),catalog=$state<DictationCatalog>(),selected=$state(''),phase=$state<DictationPhase>('idle'),transcript=$state<DictationTranscript>(emptyDictation()),text=$state(''),error=$state(''),message=$state(''),preparing=$state(false),loading=$state(false),inserting=$state(false),level=$state(0);
  let session:LiveDictation|undefined,startController:AbortController|undefined,releaseLease:(()=>Promise<void>)|undefined,leaseOwner:AbortController|undefined,disposed=false;
  const lifecycle=new AbortController();const active=$derived(preparing||['connecting','loading','microphone','listening','finishing'].includes(phase));
  const labels:Record<DictationPhase,string>={idle:'Mikrofon wyłączony',connecting:'Łączenie z silnikiem…',loading:'Przygotowywanie modelu…',microphone:'Oczekiwanie na zgodę na mikrofon…',listening:'Mikrofon włączony',finishing:'Mikrofon wyłączony · kończenie…',complete:'Sesja zakończona',error:'Sesja przerwana'};
  function fail(cause:unknown){if(!disposed&&(cause as Error).name!=='AbortError')error=(cause as Error).message||String(cause);}
  function release(owner?:AbortController){if(owner&&leaseOwner!==owner)return;const current=releaseLease;releaseLease=undefined;leaseOwner=undefined;if(current)void current().catch(fail);}
  async function reserve(current:AbortController){const leased=await acquireWidgetRuntime(current.signal);if(current.signal.aborted||disposed){await leased();current.signal.throwIfAborted();throw new DOMException('Zamknięto okno dyktowania.','AbortError');}releaseLease=leased;leaseOwner=current;}
  async function refreshStatus(){const value=await desktopDictationStatus();if(!disposed)status=value;}
  async function models(signal:AbortSignal){await remoteBackend.state(signal);const [result,prefs]=await Promise.all([productionJson<DictationCatalog>('/dictation/models',{signal}),productionJson<{model_id:string}>('/dictation/prefs',{signal})]);signal.throwIfAborted();catalog=result;if(!result.models.some(row=>row.id===selected&&row.installed))selected=result.models.find(row=>row.id===prefs.model_id&&row.installed)?.id||result.models.find(row=>row.id===result.default_model_id&&row.installed)?.id||result.models.find(row=>row.installed)?.id||'';}
  async function loadModels(){if(!desktop||active||loading)return;loading=true;error='';const current=new AbortController();startController=current;try{await reserve(current);await models(current.signal);}catch(cause){if(!current.signal.aborted)fail(cause);}finally{release(current);if(startController===current){startController=undefined;if(!disposed)loading=false;}}}
  async function start(){if(!desktop||active||loading||inserting)return;error='';message='';preparing=true;session?.cancel();release();const current=new AbortController();startController=current;try{await reserve(current);await models(current.signal);if(!selected||!catalog?.engine_available)throw new Error(catalog?.engine_reason||'Brak zainstalowanego modelu dyktowania. Przygotuj go w ustawieniach studia.');const readiness=await productionJson<{ready:boolean;missing?:{message?:string}}>(`/dictation/readiness?purpose=dictation&model_id=${encodeURIComponent(selected)}`,{signal:current.signal});current.signal.throwIfAborted();if(!readiness.ready)throw new Error(readiness.missing?.message||'Model dyktowania nie jest gotowy.');text='';transcript=emptyDictation();const next=new LiveDictation({transcript:value=>{if(!disposed&&!current.signal.aborted&&session===next){transcript=value;text=value.text;if(value.error)error=value.error;}},phase:value=>{if(disposed||session!==next)return;phase=value;if(['complete','error','idle','finishing'].includes(value))level=0;if(value==='complete'||value==='error')release(current);},activity:rms=>{if(!disposed&&session===next)level=Math.min(1,rms*4);}});session=next;await next.start({model:selected,desktop:true,origin:location.origin,workletUrl,remote:(await remoteBackend.state(current.signal)).active});if(current.signal.aborted||disposed)next.cancel();}catch(cause){if(!current.signal.aborted){phase='error';fail(cause);}release(current);}finally{if(startController===current){startController=undefined;if(!disposed)preparing=false;}}}
  function cancel(){startController?.abort();session?.cancel();release();phase='idle';preparing=false;loading=false;level=0;}
  async function hide(){cancel();try{await hideDictationWidget();}catch(cause){fail(cause);}}
  async function copy(){if(!text.trim()||inserting)return;inserting=true;error='';try{await copyDesktopDictation(text);message='Skopiowano tekst do schowka.';}catch(cause){fail(cause);}finally{if(!disposed)inserting=false;}}
  async function paste(){if(!text.trim()||active||inserting||!status?.preferences.paste_enabled||!status.target?.available)return;inserting=true;error='';try{await pasteDesktopDictation(text);message='Wysłano polecenie wklejenia do wybranego okna.';}catch(cause){fail(cause);}finally{if(!disposed){inserting=false;void refreshStatus().catch(fail);}}}
  onMount(()=>{applyAppearance(loadAppearance());void refreshStatus().catch(fail);void watchDesktopDictation({status:value=>{if(!disposed)status=value;},shown:()=>{void refreshStatus().catch(fail);},hidden:generation=>{cancel();void acknowledgeDictationStopped(generation).catch(()=>{});}},lifecycle.signal).catch(fail);});
  onDestroy(()=>{disposed=true;lifecycle.abort();cancel();});
</script>

<main class="dictation-widget" aria-label="Pływające okno dyktowania"><header><div><strong>Dyktowanie</strong><span>Seventy Seven Labs</span></div><Button type="button" variant="ghost" size="icon" aria-label="Ukryj okno i zatrzymaj mikrofon" onclick={hide}><X size={18}/></Button></header>
  <section class="widget-session"><Mic size={23}/><strong role="status">{preparing&&phase==='idle'?'Sprawdzanie gotowości…':labels[phase]}</strong><meter min="0" max="1" value={level} aria-label="Poziom sygnału mikrofonu"></meter>{#if phase==='listening'}<Button variant="default" onclick={()=>void session?.stop()}><Square size={15}/>Zatrzymaj i zakończ</Button>{:else if active}<Button variant="outline" onclick={cancel}>Anuluj sesję</Button>{:else}<Button variant="default" disabled={!desktop||loading||inserting} onclick={start}><Mic size={15}/>Rozpocznij dyktowanie</Button>{/if}</section>
  {#if !desktop}<p class="widget-note">To widok podglądu. Mikrofon i funkcje systemowe są dostępne w aplikacji desktopowej Windows.</p>{/if}
  {#if catalog}<Select label="Lokalny model" value={selected} onchange={value=>selected=value} options={catalog.models.map(row=>({value:row.id,label:row.label,disabled:!row.installed}))} disabled={active||loading||inserting}/>{/if}<Button variant="ghost" disabled={!desktop||active||loading||inserting} onclick={loadModels}><RefreshCw size={14}/>{loading?'Wczytywanie modeli…':'Wczytaj modele bez nagrywania'}</Button>
  <label for={`${uid}-text`}>Potwierdzony tekst{transcript.complete?' · wynik końcowy':''}</label><textarea id={`${uid}-text`} class="text-input widget-text" bind:value={text} readonly={active} placeholder="Kliknij Rozpocznij, aby uruchomić mikrofon. Możesz też wpisać lub wkleić własny tekst."></textarea>
  {#if transcript.partial}<p class="widget-partial" aria-live="polite"><strong>Niepotwierdzony podgląd:</strong> {transcript.partial}</p>{/if}{#if transcript.warning}<p class="widget-note">{transcript.warning}</p>{/if}
  <div class="widget-actions"><Button variant="outline" disabled={!desktop||!text.trim()||inserting} onclick={copy}><Copy size={15}/>Kopiuj tekst</Button><Button variant="default" disabled={!desktop||!text.trim()||active||inserting||!status?.preferences.paste_enabled||!status?.target?.available} onclick={paste}><ClipboardPaste size={15}/>Wklej do poprzedniego okna</Button></div>
  <p class="widget-note">{status?.preferences.paste_enabled?status.target?.available?`Cel wklejenia: ${status.target.title}`:'Aby wskazać cel, zamknij widget, aktywuj wybrany dokument i użyj globalnego skrótu.':'Przycisk wklejania włączysz w ustawieniach dyktowania Windows.'}</p>
  {#if error}<p class="widget-error" role="alert">{error}</p>{/if}{#if message}<p class="widget-note" role="status">{message}</p>{/if}<p class="widget-note">Zamknięcie lub ukrycie zatrzymuje mikrofon. Nagrywanie wymaga kliknięcia przycisku; tekst nie jest automatycznie wklejany.</p>
</main>
<style>.dictation-widget{display:flex;flex-direction:column;gap:13px;padding:18px;min-height:100%;max-width:660px;margin:auto}.dictation-widget>header{display:flex;justify-content:space-between;align-items:center;gap:15px;padding-bottom:13px;border-bottom:1px solid var(--border)}.dictation-widget>header strong{font-size:var(--ui-text-16)}.dictation-widget>header span{display:block;color:var(--muted);font-size:var(--ui-text-10);margin-top:5px}.widget-session{display:flex;flex-direction:column;align-items:center;gap:12px;padding:16px;border:1px solid var(--border);border-radius:9px}.widget-session strong{font-size:var(--ui-text-12)}.widget-session meter{width:100%;height:8px}.dictation-widget>label{font-size:var(--ui-text-12)}.widget-text{min-height:150px;flex:1;resize:vertical;font-size:15px;line-height:1.8}.widget-actions{display:flex;gap:10px;flex-wrap:wrap}.widget-actions>:global([data-slot="button"]){white-space:normal;text-align:center;flex:1;height:auto;min-height:32px}.widget-note,.widget-partial{font-size:var(--ui-text-11);line-height:1.7;color:var(--muted);white-space:pre-wrap;overflow-wrap:anywhere}.widget-partial{padding:10px;border-left:2px solid var(--border)}.widget-error{font-size:var(--ui-text-12);line-height:1.7;border:1px solid #ba5555;border-radius:7px;padding:10px;white-space:pre-wrap;overflow-wrap:anywhere}</style>
